import de.rub.nds.tlsattacker.core.quic.frame.MaxStreamDataFrame;
import de.rub.nds.tlsattacker.core.quic.frame.MaxStreamsFrame;
import de.rub.nds.tlsattacker.core.quic.frame.NewConnectionIdFrame;
import de.rub.nds.tlsattacker.core.quic.frame.QuicFrame;
import de.rub.nds.tlsattacker.core.quic.frame.ResetStreamFrame;
import de.rub.nds.tlsattacker.core.quic.frame.RetireConnectionIdFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StopSendingFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StreamDataBlockedFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StreamFrame;
import de.rub.nds.tlsattacker.core.quic.frame.StreamsBlockedFrame;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PushbackInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

/**
 * Offline layered receive audit: envelope framing, packet number reconstruction, routing,
 * authentication, key epochs, transactional frame effects and canonical wire output.
 */
public final class ReceiveAudit {

    private static final long MAX62 = (1L << 62) - 1;
    private static final long MAX60 = 1L << 60;
    private static final int I = 0;
    private static final int H = 1;
    private static final int A = 2;
    private static final String[] LEVEL = {"I", "H", "A"};
    private static final String EMPTY_HASH =
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

    // ---------------------------------------------------------------- configuration
    private long limitConnection;
    private long limitStream;
    private long limitBidi;
    private long limitUni;
    private int limitCids;
    private long localBidi;
    private long localUni;
    private int localCidWidth;
    private int localCidCount;
    private Map<String, Integer> localCidIndex = new HashMap<>();

    // ---------------------------------------------------------------- connection state
    private final boolean[] activeKeys = new boolean[3];
    private long currentEpoch;
    private final long[] largest = {-1, -1, -1};
    @SuppressWarnings("unchecked")
    private final Set<Long>[] seen = new Set[] {new HashSet<Long>(), new HashSet<Long>(), new HashSet<Long>()};
    private final RangeSet[] acks = {new RangeSet(), new RangeSet(), new RangeSet()};
    private final long[][] ecn = new long[3][3];
    private final TreeMap<Long, long[]> epochs = new TreeMap<>();
    private final TreeMap<Long, StreamState> streams = new TreeMap<>();
    private final ByteStore[] crypto = {new ByteStore(), new ByteStore(), new ByteStore()};
    private long used;
    private long openedBidi;
    private long openedUni;
    private long sendMaxData;
    private long sendMaxStreamsBidi;
    private long sendMaxStreamsUni;
    private final TreeMap<Long, PeerCid> peerCids = new TreeMap<>();
    private final Map<String, Long> cidOwners = new HashMap<>();
    private final TreeSet<Long> activePeer = new TreeSet<>();
    private long retirePriorTo;
    private final TreeSet<Integer> retiredLocal = new TreeSet<>();
    private boolean closed;
    private Map<String, Object> closedRow;

    // ---------------------------------------------------------------- packet transaction
    private final List<Undo> journal = new ArrayList<>();
    private final Map<Long, StreamState> savedStreams = new HashMap<>();
    private final RangeSet[] pendingAck = {new RangeSet(), new RangeSet(), new RangeSet()};
    private final long[][] pendingEcn = new long[3][3];
    private final boolean[] pendingEcnTouched = new boolean[3];
    private long savedUsed;
    private long savedOpenedBidi;
    private long savedOpenedUni;
    private long savedSendMaxData;
    private long savedSendMaxStreamsBidi;
    private long savedSendMaxStreamsUni;
    private long savedRetirePriorTo;

    private final MessageDigest digest = newDigest();


    private static MessageDigest newDigest() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    // ---------------------------------------------------------------- small state holders
    private static final class StreamState {
        long high;
        Long fin;
        Long reset;
        Long stop;
        long sendMax;
        /** Shared with transactional copies; the ledger journals its own mutations. */
        final ByteStore bytes;

        StreamState() {
            this.bytes = new ByteStore();
        }

        private StreamState(ByteStore bytes) {
            this.bytes = bytes;
        }

        StreamState copy() {
            StreamState c = new StreamState(bytes);
            c.high = high;
            c.fin = fin;
            c.reset = reset;
            c.stop = stop;
            c.sendMax = sendMax;
            return c;
        }
    }
